package vn.lichviet.core.fortune;

/** Câu hỏi tử vi, lịch âm thường gặp. */
public final class Faq {
    private Faq() {}

    public static final String[][] DATA = {
        {"Tuổi mụ là gì?", "Tuổi mụ (tuổi âm) = năm âm lịch hiện tại − năm sinh âm lịch + 1. Khi sinh ra đã tính 1 tuổi, qua mỗi Tết Nguyên Đán thêm 1 tuổi. Các phép xem sao hạn, kim lâu, hoang ốc đều dùng tuổi mụ."},
        {"Vì sao năm sinh âm lịch có thể khác năm dương lịch?", "Năm âm lịch bắt đầu từ Tết Nguyên Đán (thường cuối tháng 1 – giữa tháng 2 dương lịch). Người sinh tháng 1 hoặc đầu tháng 2 dương lịch có thể vẫn thuộc năm âm lịch trước."},
        {"Mệnh (nạp âm) là gì?", "Mỗi cặp can chi năm sinh ứng với một nạp âm như Lộ Bàng Thổ, Kiếm Phong Kim. Hành cuối (Kim, Mộc, Thủy, Hỏa, Thổ) là bản mệnh, dùng để xem màu sắc, tuổi hợp, nghề nghiệp."},
        {"Cung phi khác mệnh như thế nào?", "Cung phi (Bát trạch) tính theo năm sinh và giới tính, dùng để chọn hướng nhà, hướng bàn làm việc. Mệnh nạp âm dùng cho màu sắc, tuổi hợp. Hai cách tính độc lập nhau."},
        {"Sao hạn là gì?", "Mỗi năm có một trong chín sao (Cửu Diệu) chiếu mệnh, xác định theo tuổi mụ và giới tính, 9 năm lặp lại. Thường chia 3 sao tốt (Thái Dương, Thái Âm, Mộc Đức), 3 sao trung (Vân Hớn, Thổ Tú, Thủy Diệu), 3 sao xấu (La Hầu, Kế Đô, Thái Bạch)."},
        {"Hạn là gì?", "Ngoài sao còn có 8 hạn: Huỳnh Tuyền, Tam Kheo, Ngũ Mộ, Thiên Tinh, Toán Tận, Thiên La, Địa Võng, Diêm Vương. Đại hạn là Huỳnh Tuyền, Toán Tận; tiểu hạn là Tam Kheo, Ngũ Mộ."},
        {"Tam tai là gì?", "Ba năm liên tiếp được cho là dễ gặp trắc trở, tính theo nhóm tam hợp: Thân Tý Thìn gặp năm Dần Mão Thìn; Dần Ngọ Tuất gặp năm Thân Dậu Tuất; Tỵ Dậu Sửu gặp năm Hợi Tý Sửu; Hợi Mão Mùi gặp năm Tỵ Ngọ Mùi."},
        {"Kim lâu là gì?", "Lấy tuổi mụ chia 9: dư 1 là Kim Lâu Thân, dư 3 Kim Lâu Thê, dư 6 Kim Lâu Tử, dư 8 Kim Lâu Lục Súc. Dân gian kiêng cưới hỏi, làm nhà vào năm phạm Kim lâu."},
        {"Hoang ốc là gì?", "Sáu cung: Nhất Cát, Nhì Nghi, Tam Địa Sát, Tứ Tấn Tài, Ngũ Thọ Tử, Lục Hoang Ốc. Khởi 10 tuổi ở Nhất Cát, 20 tuổi ở Nhì Nghi..., mỗi năm lẻ đếm tiếp một cung. Cung 1, 2, 4 tốt; 3, 5, 6 xấu."},
        {"Giờ hoàng đạo là gì?", "Mỗi ngày có 6 giờ (canh giờ 2 tiếng) hoàng đạo được xem là giờ tốt để khởi sự việc quan trọng như xuất hành, khai trương, cưới hỏi."},
        {"Ngày hoàng đạo và hắc đạo khác nhau thế nào?", "Mỗi ngày do một trong 12 vị thần trực. Sáu thần tốt (Thanh Long, Minh Đường, Kim Quỹ, Thiên Đức, Ngọc Đường, Tư Mệnh) cho ngày hoàng đạo; còn lại là hắc đạo."},
        {"Tam Nương, Nguyệt Kỵ là gì?", "Tam Nương là các ngày 3, 7, 13, 18, 22, 27 âm lịch; Nguyệt Kỵ là ngày 5, 14, 23. Dân gian kiêng khởi sự việc lớn vào những ngày này."},
        {"Mượn tuổi là gì?", "Khi gia chủ phạm kim lâu, hoang ốc hay tam tai, có thể nhờ người tuổi hợp đứng ra làm lễ động thổ, cưới hỏi thay để hóa giải theo phong tục."},
        {"Thông tin trong ứng dụng lấy từ đâu?", "Mỗi màn hình đều ghi nguồn ở cuối. Các quy tắc tính được đối chiếu với nhiều trang báo và trang tử vi phổ biến của Việt Nam. Đây là phong tục dân gian mang tính tham khảo văn hóa, không có cơ sở khoa học kiểm chứng."},
    };
}
